# receive_kill12/tools/rk_status.py — RECEIVE_KILL12_STATUS.json from the evidence: python3 rk_status.py <receive_kill12 review dir>
import json, os, sys
R = sys.argv[1]; EV = os.path.join(R, "evidence"); J = lambda f: json.load(open(os.path.join(EV, f)))
T3, WB, DET, CH, CPU, REG, RC, SCK = J("rk12_three_scales.json"), J("rk12_whatif_B.json"), J("rk12_determinism.json"), J("rk12_chrome_node.json"), J("rk12_cpu.json"), J("rk12_regression.json"), J("receive11_matrix_714_rerun_compare.json"), J("rk12_scalecheck.json")
def row(r): return {"g": r["g"], "E": r["E"], "immediate": r["cls"]["IMMEDIATE"], "classes": r["cls"], "residMedian": r["resid"]["med"], "placeMedian": r["place"]["med"], "e025Median": r["e025"]["med"], "e05Median": r["e05"]["med"], "e1Median": r["e1"]["med"], "d2Median": r["d2"]["med"], "recDistMedian": r["recDist"]["med"], "recTimeMedian": r["recTime"]["med"], "contactsMean": r["contacts"]["mean"], "tStableMedian": r["tStable"]["med"]}
bench = {bid: {"title": B["title"], "surface": B["scales"]["candidate"][0]["surface"], "D": B["scales"]["candidate"][0]["D"], "byScale": {sc: {str(r["bc"]): row(r) for r in B["scales"][sc]} for sc in ["original", "current", "candidate"]}, "whatIfB": {str(r["bc"]): row(r) for r in WB["benchmarks"][bid]}, "anchors": B["anchors"]} for bid, B in T3["benchmarks"].items()}
hard = T3["benchmarks"]["HARD"]["scales"]
S = {"milestone": "RECEIVE-KILL-1.2", "date": "2026-10-18", "branch": "prototype/dribble-1", "frozen": False, "curveLocked": False, "integratedIntoReceiveControl11": False,
  "readyToFreeze": "NO — presented for the owner's review ('Do NOT freeze the new curve. Show it to me first.')",
  "model": {"original": "E = 0.0068 + 0.40 · u^1.1 · D/(D+1), u = (100−BC)/90; chest k [1.0,0.6,0.6], head k [1.0,0.9,0.6]",
            "current": "E = 0.0068 + 0.25 · u·(0.68 + 0.32·u²) · D/(D+1); chest k [0.85,0.5,0.5], head k [0.85,0.7,0.5]",
            "candidate": "E_new(BC, D) = E_current(g(BC), D); g = monotone cubic (PCHIP, Fritsch–Carlson) through " + ", ".join(f"({b}, {g})" for b, g in [[1, -8.5], [10, 0.7], [50, 40], [75, 50], [99, 98.5]]) + "; everything else = RECEIVE-KILL-1.1",
            "gTable": {str(r["bc"]): r["g"] for r in hard["candidate"]}, "E22": {sc: {str(r["bc"]): r["E22"] for r in hard[sc]} for sc in ["original", "current", "candidate"]}},
  "anchors": {"metExactly": True, "note": "the PCHIP passes through (75, 50) and (50, 40), so new BC75 and new BC50 have exactly current BC50's and BC40's error; with matched seeds the episodes are identical (same class per seed 100 % on every benchmark)", "byBenchmark": {bid: B["anchors"] for bid, B in T3["benchmarks"].items()}},
  "tension": "the anchors put 25 new points (50→75) on 10 current points (40→50): ratings 50–75 differ less than in RECEIVE-KILL-1.1 (22 m/s immediate 33/39/45/49 % at new 50/60/70/75 vs current 49/69/85/89 %), and 70–90 sit at about the ORIGINAL model's error (current BC50's error is already larger than the original's at BC75). What-if B (anchors within 10 %) widens 50–75 to 29/37/47/57 % with 80 = 73 %, 90 = 95 %.",
  "whatIfB": {"knots": WB["knots"], "status": "review evidence only, not built into the pages", "gTable": {str(r["bc"]): r["g"] for r in WB["benchmarks"]["HARD"]}},
  "benchmarks": bench, "seeds": T3["nSeeds"],
  "determinism": {"currentScaleEqualsReceiveKill11": f'{SCK["current"]["identical"]}/{SCK["current"]["runs"]}', "originalScaleEqualsReceiveKill1": f'{SCK["original"]["identical"]}/{SCK["original"]["cells"]}', "drawsIdenticalAcrossBC": f'{DET["matched"]["drawsIdenticalAcrossBC"]}/{DET["matched"]["drawsChecked"]}', "firstContactProportional": f'{DET["matched"]["proportional"]}/{DET["matched"]["proportionalChecked"]}', "replay": f'{DET["replay"]["identical"]}/{DET["replay"]["runs"]}', "schedulePath": f'{DET["schedulePath"]["identical"]}/{DET["schedulePath"]["runs"]}', "animationOnOff": f'{DET["anim"]["identical"]}/{DET["anim"]["runs"]}', "chromeNode": f'{CH["identical"]}/{CH["total"]}'},
  "cpu": {g: {"firstContactMs": round(c["firstContactMs"], 4), "wholeEpisodeMs": round(c["wholeEpisodeMs"], 3), "worstEpisodeMs": round(c["worstEpisodeMs"], 3)} for g, c in CPU["groups"].items()},
  "regression": {"receiveKill11Episodes": f'{REG["kill11MatchEvidenceAfter"]}/{REG["kill11Cells"]}', "receiveKill1Cells": f'{REG["kill1MatchEvidenceAfter"]}/{REG["kill1Cells"]}', "dribbleV1": f'{REG["dribbleBeforeEqualsAfter"]}/{REG["dribbleRuns"]}', "dribbleV1Evidence": f'{REG["dribbleEvidenceMatch"]}/{REG["dribbleEvidenceCompared"]}', "receive11Cases": f'{REG["receive11BeforeEqualsAfter"]}/{REG["receive11Cases"]}', "receive11Matrix": f'{RC["identical"]}/{RC["runs"]}', "frozenParamsUnchanged": REG["frozenParamsUnchanged"], "frozenFiles": "IDENTICAL" if "IDENTICAL" in open(os.path.join(EV, "frozen_sha256_end_check.txt")).read() else "CHANGED"},
  "limitations": ["placeholder body, not in the ball's world", "stationary receiver in clean conditions; adjustment speed and foot timing fixed (Agility / Dribbling later)", "a pure remap: the candidate cannot produce any outcome the current scale does not produce at some rating", "follow-ups are foot controls only", "curve not locked"],
  "review": "review/RECEIVE_KILL12_REVIEW.html (local only)"}
json.dump(S, open(os.path.join(R, "RECEIVE_KILL12_STATUS.json"), "w"), indent=1, ensure_ascii=False); print("wrote status")
